-- V-L22 (run O1, lane otkdata): after L22-l1-otakudle-facts-corrections.sql, the Otakudle facts.
-- Read only, in a read-only transaction. Each row is: ok or KO | what | the number found. Never a name of a person, an e-mail or a target of a day.
begin transaction read only;
select case when ok is true then 'ok' else 'KO' end, what, coalesce(got, '-') from (values
  (1, '751 lignes de faits (750 de L13 plus Ken Kaneki)', (select count(*) = 751 from public.character_facts), (select count(*)::text from public.character_facts)),
  (2, '208 personnages en vedette (200 de TOP200, plus 9, moins Haise Sasaki)', (select count(*) = 208 from public.character_facts where featured), (select count(*)::text from public.character_facts where featured)),
  (3, 'Otakudle : 204 cibles possibles (185 avant L22 : 20 de plus, Haise Sasaki en moins)', (select count(*) = 204 from public.dle_entities where game_id = 'otakudle' and can_be_target and in_pool), (select count(*)::text from public.dle_entities where game_id = 'otakudle' and can_be_target and in_pool)),
  (4, 'Ken Kaneki est une cible, Haise Sasaki et Rimuru Tempest ne le sont pas', (select count(*) = 3 from public.dle_entities e join public.characters c on c.id::text = e.entity_id where e.game_id = 'otakudle' and ((c.slug = 'ken-kaneki' and e.can_be_target) or (c.slug in ('haise-sasaki', 'rimuru-tempest') and not e.can_be_target))), null),
  (5, 'le doublon Hisoka (hisoka-morrow) est hors du pool, hisoka-morow y reste', (select count(*) = 2 from public.dle_entities e join public.characters c on c.id::text = e.entity_id where e.game_id = 'otakudle' and ((c.slug = 'hisoka-morrow' and not e.in_pool) or (c.slug = 'hisoka-morow' and e.in_pool))), null),
  (6, 'doubleurs : aucune valeur en japonais, aucun nom écrit nom de famille d''abord (Re:Zero, Sword Art Online)', (select count(*) = 0 from public.character_facts f join public.characters c on c.id = f.character_id join public.groups g on g.id = c.group_id where f.voice_actor_ja ~ '[぀-ヿ一-鿿]' or (g.slug in ('re-zero', 'sword-art-online') and f.voice_actor_ja ~ '^(Kobayashi|Matsuoka|Tomatsu|Sawashiro|Yuuki|Murakawa|Minase|Nakamura|Takahashi|Arai|Iguchi|Sakamoto|Amasaki|Eguchi|Okamoto|Taketatsu|Itou|Hidaka|Takagaki|Hirata|Ohkawa|Izawa|Shimazaki) ')), null),
  (7, 'Tokyo Revengers : 12 doubleurs, aucun n''est le nom du personnage', (select count(*) = 12 from public.character_facts f join public.characters c on c.id = f.character_id join public.groups g on g.id = c.group_id where g.slug = 'tokyo-revengers' and f.voice_actor_ja is not null and f.voice_actor_ja !~ '[぀-ヿ一-鿿]'), null),
  (8, 'chaque personnage en vedette avec un rôle a une source pour ce rôle', (select count(*) = 0 from public.character_facts f join public.characters c on c.id = f.character_id where f.featured and f.role_at_debut is not null and not exists (select 1 from public.entity_sources s where s.entity_type = 'character' and s.field = 'role_at_debut' and (s.entity_id = c.slug or s.entity_id like '%/' || c.slug))), (select count(*)::text from public.character_facts f join public.characters c on c.id = f.character_id where f.featured and f.role_at_debut is not null and not exists (select 1 from public.entity_sources s where s.entity_type = 'character' and s.field = 'role_at_debut' and (s.entity_id = c.slug or s.entity_id like '%/' || c.slug)))),
  (9, 'sources de L22 : une adresse et une révision numérique chacune', (select count(*) >= 150 from public.entity_sources s where s.entity_type = 'character' and s.fetched_at = '2026-11-09T00:00:00Z' and s.source_ref ~ '^[0-9]+$' and s.source_url ~ '^https://'), (select count(*)::text from public.entity_sources s where s.entity_type = 'character' and s.fetched_at = '2026-11-09T00:00:00Z')),
  (10, 'species et sexe : Captain Ginyu masculin, Neferpitou sans sexe, Mr. Popo sans espèce', (select count(*) = 3 from public.character_facts f join public.characters c on c.id = f.character_id where (c.slug = 'captain-ginyu' and f.gender = 'male') or (c.slug = 'neferpitou' and f.gender is null and f.species = 'chimera-ant') or (c.slug = 'mr-popo' and f.species is null)), null)
) as c(n, what, ok, got) order by n;
rollback;
